using System.Collections.Generic;
using System.Net.Http;
using System.Net.Http.Json;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;

namespace Acme.Sync;

public sealed class InventorySynchronizer
{
    private readonly HttpClient _http;
    private readonly IInventoryStore _store;
    private readonly ILogger<InventorySynchronizer> _logger;

    public async Task SyncAllAsync(IReadOnlyList<string> warehouseIds)
    {
        foreach (var warehouseId in warehouseIds)
        {
            var response = await _http.GetAsync($"/warehouses/{warehouseId}/stock");
            var items = await response.Content.ReadFromJsonAsync<List<StockItem>>();
            await _store.UpsertAsync(items);
        }
    }
}

using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;

namespace Acme.Sync;

public sealed class InventorySyncWorker : BackgroundService
{
    private readonly InventorySynchronizer _synchronizer;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await _synchronizer.SyncAllAsync(await LoadWarehouseIdsAsync());
            await Task.Delay(TimeSpan.FromMinutes(15), stoppingToken);
        }
    }
}

