public async Task SyncAllAsync(IReadOnlyList<string> warehouseIds, CancellationToken cancellationToken = default)
{
    try
    {
        foreach (var warehouseId in warehouseIds)
        {
            await SyncOneAsync(warehouseId, cancellationToken);
        }
    }
    catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
    {
        _logger.LogInformation("inventory sync cancelled by host");
        throw;
    }
}

private async IAsyncEnumerable<StockItem> ReadStockAsync(
    string warehouseId,
    [EnumeratorCancellation] CancellationToken cancellationToken = default)
{
    for (var page = 1; ; page++)
    {
        var url = $"/warehouses/{warehouseId}/stock?page={page}";
        var items = await _http.GetFromJsonAsync<List<StockItem>>(url, cancellationToken);
        if (items is not { Count: > 0 }) yield break;
        foreach (var item in items) yield return item;
    }
}

private async Task SyncOneAsync(string warehouseId, CancellationToken cancellationToken)
{
    await foreach (var item in ReadStockAsync(warehouseId).WithCancellation(cancellationToken))
    {
        await _store.UpsertAsync(item, cancellationToken);
    }
}

foreach (var warehouseId in warehouseIds)
{
    using var perWarehouse = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
    perWarehouse.CancelAfter(TimeSpan.FromSeconds(30));
    try
    {
        await SyncOneAsync(warehouseId, perWarehouse.Token);
    }
    catch (OperationCanceledException)
    {
        _logger.LogWarning("warehouse {WarehouseId} timed out", warehouseId);
    }
}
